pid_t target_pid = 0; // 0 = Current process
pid_t new_pgid = 0;    // 0 = Use target_pid as PGID

// Set the current process as the leader of a new process group
if (setpgid(target_pid, new_pgid) == -1) {
    // Common errors: EPERM, EACCES
    perror("setpgid failed to create new group");
}

// Example: Move a child process (child_id) into the parent's group (pgid)
pid_t child_id = 1234;
pid_t parent_pgid = getpgid(0);

if (setpgid(child_id, parent_pgid) == -1) {
    perror("setpgid failed to join group");
}
